/* 💥 朋友圈背景图高度重置 (大幅下拉) */
:root {
    --nj-msg-moments-cover-height: 380px !important; 
}
.nj-moments-cover { height: 380px !important; margin-bottom: 0 !important; }
.nj-moments-cover-avatar { transform: translateY(-10px) !important; border: none !important; box-shadow: none !important; border-radius: 8px !important; width: 78px !important; height: 78px !important; aspect-ratio: 1 / 1 !important; background: transparent !important; overflow: hidden !important; }
.nj-moments-cover-avatar img { border-radius: 8px !important; width: 100% !important; height: 100% !important; object-fit: cover !important; }
