}

/* ==========================================
   2. 消息列表 / 置顶笔记 
   ========================================== */
.nj-chat-tab-header { background-color: #ededed !important; border-bottom: none !important; padding-top: calc(10px + var(--nuo-safe-top, 0px)) !important; }
.nj-chat-tab-header-title-btn { color: transparent !important; position: relative !important; }
.nj-chat-tab-header-title-btn::after { content: '微信'; position: absolute; left: 50%; top: 50%; transform: translate(-50%, -50%); color: #191919; font-size: 17px; font-weight: 600; pointer-events: none; }
.nj-chat-tab-header-back { color: transparent !important; position: relative !important; }
.nj-chat-tab-header-back::after { content: '☆'; position: absolute; left: 2px !important; top: 50%; transform: translateY(-50%); color: #191919; font-size: 24px; font-weight: 200 !important; pointer-events: none; }
.nj-chat-tab-header-edit { color: transparent !important; position: relative !important; }
.nj-chat-tab-header-edit::after { content: '⊕'; position: absolute; right: 2px !important; top: 50%; transform: translateY(-50%); color: #191919; font-size: 26px; font-weight: 200 !important; pointer-events: none; }

.nj-chat-tab-search-wrap { background-color: #ededed !important; padding: 6px 8px 12px 8px !important; }
.nj-chat-tab-search { position: relative !important; margin: 0 !important; width: 100% !important; background-color: #ffffff !important; border-radius: 6px !important; height: 36px !important; display: flex !important; justify-content: center !important; align-items: center !important; }
.nj-chat-tab-search input::-webkit-input-placeholder, .nj-chat-tab-search input::placeholder { color: transparent !important; opacity: 0 !important; }
.nj-chat-tab-search > svg, .nj-chat-tab-search > img, .nj-chat-tab-search > i { display: none !important; }
.nj-chat-tab-search input { padding-left: 0 !important; background-image: none !important; }
.nj-chat-tab-search::before { content: '搜索'; position: absolute; left: 50%; top: 50%; transform: translate(-50%, -50%); color: #b2b2b2; font-size: 16px; pointer-events: none; padding-left: 22px; background-image: url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="%23b2b2b2" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="11" cy="11" r="8"/><line x1="21" y1="21" x2="16.65" y2="16.65"/></svg>'); background-size: 16px; background-position: left center; background-repeat: no-repeat; z-index: 2; }

.nj-chat-tab-notes { display: none !important; }
.nj-chat-tab-list::before { 
    content: var(--cfg-chat-note) !important; 
    display: block !important; 
    width: 100% !important; 
    box-sizing: border-box !important; 
    background-color: #ededed !important; 
    padding: 13px 16px 13px 76px !important; 
    color: #555555 !important; 
    font-size: 13.5px !important; 
    font-weight: 400 !important; 
    line-height: 1.4 !important; 
    background-image: url('https://imgbed.heliar.top/i/P_wboUzan_-86k2V.png') !important; 
    background-size: 19px !important; 
    background-position: 31px center !important; 
    background-repeat: no-repeat !important; 
    border-bottom: 1px solid rgba(0,0,0,0.04) !important; 
    pointer-events: none !important; 
}

.nj-chat-tab-list { background-color: #ffffff !important; }
.nj-chat-tab-section-title { display: none !important; }
.nj-chat-item { margin: 0 !important; padding: 12px 16px !important; background-color: var(--nj-msg-card-bg) !important; position: relative !important; }
.nj-chat-item-pinned { background-color: #ededed !important; }
.nj-chat-item-avatar { width: 48px !important; height: 48px !important; border-radius: 6px !important; }
.nj-chat-item-pinned .nj-chat-item-time::after, .nj-chat-item-pinned .nj-chat-item-time::before, .nj-chat-item-pinned .nj-chat-item-badge, .nj-chat-item-pinned [class*="pin"], .nj-chat-item-pinned [class*="pinned"]:not(.nj-chat-item-pinned), .nj-chat-item-pinned .nj-chat-item-time svg, .nj-chat-item-pinned .nj-chat-item-time img, .nj-chat-item-pinned .nj-chat-item-time i { display: none !important; visibility: hidden !important; opacity: 0 !important; }
.nj-chat-item::after { content: '' !important; position: absolute !important; left: 76px !important; right: 0 !important; bottom: 0 !important; height: 1px !important; background-color: rgba(0, 0, 0, 0.06) !important; transform: scaleY(0.5) !important; }
.nj-chat-item-name { font-size: 16px !important; color: #191919 !important; font-weight: 400 !important; }
.nj-chat-item-time { font-size: 12px !important; color: #b2b2b2 !important; }
.nj-chat-item-preview { font-size: 14px !important; color: #b2b2b2 !important; margin-top: 4px !important; }

