/* 💥 3. 朋友圈 (Moments) */
#messaging-moments-tab, .nj-moments-feed, .nj-moments-post { background-color: #ffffff !important; }
.nj-moments-notif-entry, .nj-moments-cover-gradient { display: none !important; }
