/* 💥 修复朋友圈互动触发按钮 (控制大小 + 换回日间版浅灰图标) */
.nj-moments-post-actions-trigger { 
    background-image: url('https://imgbed.heliar.top/i/Yrhf-UHdV3JtghqS_IMG_0513.webp') !important; 
    background-size: contain !important; /* 关键：保证图片完整显示不被拉伸 */
    background-position: center !important; 
    background-repeat: no-repeat !important; 
    background-color: transparent !important; /* 用图片自带的底色，去掉多余背景 */
    color: transparent !important; 
    width: 36px !important; /* 严格限制按钮宽度 */
    height: 22px !important; /* 严格限制按钮高度 */
    border: none !important; 
    border-radius: 4px !important; 
    padding: 0 !important; 
}
.nj-moments-post-actions-trigger svg, .nj-moments-post-actions-trigger img { display: none !important; }

/* 夜间模式保持深色版 */
