value.customCss:
/* 微信日间/浅色模式全局强制设定 */
.xt-root {
    --xt-bg: #f2f2f2;
    --xt-text: #000000;
    --xt-text-sub: #7f7f7f;
    --xt-border: #ededed;
    --xt-radius: 0px; 
    padding: 0 !important;
    background-color: #f2f2f2 !important;
    color: #000000 !important;
}

.xt-content {
    background-color: #f2f2f2 !important;
}

/* 顶部个人信息区域 (纯白底) */
.xt-header {
    position: relative;
    padding: 20px 20px 60px 20px;
    background-color: #ffffff !important;
    align-items: flex-start;
}

/* 微信标志性圆角矩形头像 */
.xt-avatar {
    width: 64px !important;
    height: 64px !important;
    border-radius: 8px !important; 
    margin-right: 15px;
}

.xt-name {
    font-size: 20px;
    font-weight: 500;
    margin-top: 2px;
    color: #191919 !important;
}

/* 绝对定位：微信号（已清除底色） */
.xt-text-wechatId {
    position: absolute;
    top: 50px;
    left: 99px;
    color: #7f7f7f !important;
    font-size: 13px;
    background: transparent !important;
}
.xt-text-wechatId::before { content: "微信号: "; }

/* 绝对定位：状态与朋友（已清除底色） */
.xt-text-friendZone {
    position: absolute;
    top: 76px;
    left: 99px;
    color: #7f7f7f !important;
    font-size: 12px;
    background: transparent !important;
}
.xt-text-friendZone::before {
    content: "+ 状态";
    border: 1px solid #e0e0e0;
    border-radius: 12px;
    padding: 2px 8px;
    margin-right: 8px;
    color: #576b95;
    background-color: transparent !important;
}

/* 浅灰分隔槽 */
.xt-spacer {
    background-color: #f2f2f2 !important;
    height: 8px !important;
}

/* 菜单项外壳 */
.xt-collapse {
    background-color: #ffffff !important;
    border: none;
    margin: 0;
    border-bottom: 1px solid #ededed;
}

/* 菜单项标题行 */
.xt-collapse-header {
    background-color: #ffffff !important;
    color: #191919 !important;
    padding: 16px 20px;
    font-size: 16px;
    font-weight: 400;
}

/* 箭头颜色 */
.xt-collapse-arrow {
    color: #b2b2b2 !important;
}

/* 展开区域容器 */
.xt-collapse-body {
    background-color: #ffffff !important;
    padding: 0 20px 0 40px; 
    border-bottom: 1px solid #ededed;
}

/* 把间距加到子元素文字上 */
.xt-text-innerVoice, .xt-list-item,
.xt-text-songInfo, .xt-text-songLyric, .xt-text-songThought {
    color: #333333 !important;
    font-size: 14px;
    padding: 8px 0; 
    line-height: 1.4;
}

/* 隐藏列表的小圆点 */
.xt-list-check { display: none; }

/* --- 第三框（正在听）排版 --- */
.xt-text-songInfo { 
    color: #191919 !important; 
    font-weight: 500; 
}

/* 歌词自动加上双引号 */
.xt-text-songLyric { 
    color: #666666 !important; 
    font-style: italic;
    font-size: 13px;
}
.xt-text-songLyric::before {
    content: "“";
}
.xt-text-songLyric::after {
    content: "”";
}

.xt-text-songThought { 
    color: #555555 !important; 
    padding-bottom: 16px;
}

