# ============ 顶部新版头 (图二风格) ============
@text headerTop
@divider
@text headerMain

# ============ 第一篇文章：无厘头新闻 ============
@text newsTitle
@text newsContent

@image pic1
@text caption1

# ============ 第二篇文章：文艺独白 ============
@text voiceTitle
@text innerVoice

@image pic2
@text caption2

# ============ 进程版头 (大字报排版) ============
@text progressSub
@text progressTitle
@text progressTag1
@text progressTag2

# ============ 互动小板块 ============

# 1. 刮刮乐悄悄话
@card "未公开独白"
  @text secretWhisper
  @toggle 1
@endcard

# 2. 完美的左右双栏：左快报 | 右广告 (强制直线)
@row 2
  @text shortNews
  @text adText
@endrow

# 3. 规章制度
@section ◆ 今日注意事项 ◆
  @list
    rule1
    rule2
    rule3

# ============ 底部：高级杂志风访谈 ============
@text interviewTop

@row 2
  @card " "
    @text charName
    @text interviewTitle
    @text interviewQuestion
  @endcard

  @card " "
    @text interviewContent
  @endcard
@endrow

