value.layout:
# ── 1. 首页排版 ──
@row 2
@text letterTitle
@card
  @image charImage
  @text charAlias
@endcard
@endrow

@text innerVoice
@divider
@text chapterTag
@text footerText

# ── 2. 底部触发：真心话浮窗（未删减与正文整体居中） ──
@toggle 1
@spacer 10
@text falseTitle
@card
  @text poemSubTitle
  @text pLine1
  @text pLine2
  @text pLine3
@endcard

# ── 3. 头像触发：短章浮窗 ──
@toggle 2
@spacer 10
@text shortTitle
@card
  @text sLine1
  @text sLine2
  @text sLine3
  @text sLine4
  @text sLine5
  @text sLine6
@endcard
@text shortTag
@text shortFoot

# ── 4. 标题触发：下划线极简聊天 ──
@toggle 3
@spacer 10
@text chatTime
@bubbles
  chatLine1:left
  chatLine2:right
  chatLine3:left
  chatLine4:right
  chatLine5:right

# ── 5. Chapter End 触发：如果平行小剧场 ──
@toggle 4
@spacer 10
@text theatreTitle
@card
  @text tP1
  @text tP2
  @text tP3
@endcard
@text theatreSign

# ── 6. 正文独白触发：季节随笔日记 ──
@toggle 5
@spacer 10
@text diaryTitle
@text diarySub
@card
  @text dP1
  @text dP2
  @text dP3
  @text dP4
@endcard
@text diarySign
@text diaryDate

